pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(amount > 0 && amount <= address(this).balance);
        Reverter reverter = new Reverter();
        // Deposit to the reverter, then let it withdraw from the real c.
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();
        // Now make the reverter act as the caller for withdrawAll.
        // The reverter's receive() will revert, so the call returns false.
        // In P, the transaction reverts entirely; in M, it succeeds but corrupts state.
        bool reverted;
        vm.prank(address(reverter));
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        // The invariant: if withdrawAll did NOT revert, then the contract balance must be zero.
        // For P, a revert always happens when the recipient fails, so invariant holds vacuously (withdrawAll never succeeds).
        // For M, withdrawAll succeeds, the reverter gets no ETH, but credit is zeroed and balance is reduced → balance ≠ 0 while invoking invariant.
        // We read balance through a public getter? No public getter exists for `balance`, but we can read `address(c).balance`.
        // Since all deposited ETH was credited to the reverter, after withdrawAll credit[reverter] = 0, so if balance > 0 invariant is broken.
        assertTrue(reverted || address(c).balance == 0);
    }
}

contract Reverter {
    receive() external payable { revert(); }
}

