import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 seed) public {
        // Keep amount in a reasonable range to avoid overflow on the deposit side
        amount = bound(amount, 1, 1e24);
        address caller = address(uint160(seed));
        vm.assume(caller != address(0) && caller != address(this) && caller.code.length == 0);

        // Give the caller some ETH to deposit
        vm.deal(caller, amount);
        vm.prank(caller);
        c.deposit{value: amount}();

        // Deploy an adversarial callee that REVERTS on receiving ETH
        Reverter reverter = new Reverter();
        // The caller transfers its entire credit to the reverter, so the reverter will be the one calling withdrawAll
        vm.prank(caller);
        c.withdrawAll(); // This withdraws to caller (EOA, always succeeds), leaving credit=0

        // Now deposit again, but into the reverter address so the reverter is the creditor
        vm.deal(caller, amount);
        vm.prank(caller);
        c.deposit{value: amount}();
        // Transfer credit from caller to reverter: no such function, so instead deposit directly as reverter
        // Actually we need the reverter to be the creditor. Let's just deposit as the reverter.
        vm.deal(address(reverter), amount);
        vm.prank(address(reverter));
        c.deposit{value: amount}();

        // Now reverter calls withdrawAll; it will be the msg.sender and its receive will revert
        vm.prank(address(reverter));
        try c.withdrawAll() {
            // If the call succeeds (should not happen because Reverter reverts on receive)
            // In the reference, this line is unreachable because require(callResult) reverts
            // In the buggy version, it does NOT revert, so execution reaches here
        } catch {
            // In the reference, we always end up here. In the buggy, we might not.
            // We need an assertion that holds for reference for ALL inputs but fails for buggy for SOME.
            // We'll assert on the credit of the reverter after the withdrawal attempt.
        }

        // The invariant: after a non-reverting withdrawAll, the caller's credit must be zero.
        // In the reference, the reverter's withdrawAll always reverts, so the invariant "if it doesn't revert, credit=0"
        // is vacuously true. In the buggy version, withdrawAll can succeed (not revert) while the credit is zeroed
        // but ETH not transferred, so credit=0 is true in that case too. Not distinguishing.

        // Better invariant: the caller's credit after ANY execution of withdrawAll (whether it reverted or not)
        // must either be zero (if the withdrawal succeeded) OR remain unchanged (if it reverted).
        // In the buggy version, if the call fails, credit is already zeroed but the withdrawal didn't succeed,
        // so the credit becomes zero incorrectly.

        // Let's read credit: there is no public getter because mapping is not public. So we cannot read credit directly.
        // We can only observe balance or external behavior. Let's re-approach.
    }
}

