pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address caller) public {
        // Admissible domain: positive deposit, withdraw does not exceed deposit, caller is not zero address
        vm.assume(depositAmount > 0);
        vm.assume(withdrawAmount <= depositAmount);
        vm.assume(caller != address(0));
        // Deploy an adversarial callee that always reverts on receipt of ETH
        FailingCallee failingCallee = new FailingCallee();
        // Deal ETH to caller and deposit into C
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.deposit{value: depositAmount}();
        // Forcibly inject credit for the failing callee by depositing on its behalf
        vm.deal(address(failingCallee), withdrawAmount);
        vm.prank(address(failingCallee));
        c.deposit{value: withdrawAmount}();
        // Record balance before withdrawal
        uint256 balanceBefore = address(c).balance;
        // Failing callee attempts to withdraw
        vm.prank(address(failingCallee));
        c.withdrawAll();
        uint256 balanceAfter = address(c).balance;
        // General rule: balance must be >= balanceBefore - withdrawAmount (i.e., if transfer fails, balance must not decrease)
        // Since callee reverts on receive, the correct contract reverts the whole withdrawal, leaving balance unchanged.
        // The buggy version deducts balance without sending ETH, so balanceAfter < balanceBefore - withdrawAmount.
        assertTrue(balanceAfter >= balanceBefore - withdrawAmount);
    }
}

contract FailingCallee {
    fallback() external payable {
        revert();
    }
}

