pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address actor) public {
        vm.assume(depositAmount > 0 && withdrawAmount > 0);
        vm.assume(depositAmount <= 1e30 && withdrawAmount <= 1e30);
        vm.assume(actor != address(0) && actor != address(this));

        // Set up actor with depositAmount
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();

        // Actor withdraws withdrawAmount via withdrawAll
        // withdrawAll withdraws all credit, but we need actor to have exactly withdrawAmount credit.
        // We do another deposit/withdraw to set credit appropriately, but the simplest is:
        // Ensure actor's credit equals withdrawAmount by manipulating deposits.
        // However, we cannot directly set credit. We'll deposit again if needed, but it's easier:
        // Let the actor deposit enough such that after a previous full withdraw, it has withdrawAmount.
        // Actually, the test should just call withdrawAll and verify the invariant holds.
        // The invariant is: balance == address(c).balance.
        // We just need to ensure the call to withdrawAll succeeds (does not revert on transferring ETH).
        // But withdrawAmount must not exceed the actor's credit. Since actor deposited depositAmount,
        // its credit is depositAmount. We need withdrawAmount <= depositAmount.
        vm.assume(withdrawAmount <= depositAmount);

        // To test the invariant, we need the actor to have exactly withdrawAmount credit.
        // If withdrawAmount < depositAmount, the actor currently has depositAmount credit.
        // We can make the actor withdraw the excess first? But that changes balance.
        // A simpler approach: use a separate deposit for the exact withdrawAmount.
        // Let's reset actor and deposit exactly withdrawAmount.
        // Re-deploy or use a fresh actor? We can just use actor2, but the test has only one actor param.
        // We can just let the actor deposit withdrawAmount directly, but it already deposited depositAmount.
        // We'll just verify the invariant after the first deposit and after withdrawAll;
        // the invariant should hold regardless of the amounts. The bug exposes a difference when withdrawAll is called.
        // So we just call withdrawAll and check the invariant.

        vm.prank(actor);
        c.withdrawAll();

        // Assert invariant: contract's ETH balance equals internal balance
        assertTrue(address(c).balance == c.balance());
    }
}

