pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 depositAmount, uint8 attackerAmount, uint8 attackerIndex) public {
        // Keep amounts positive and within a modest range to avoid overflow in repeated operations
        vm.assume(depositAmount > 0);
        vm.assume(attackerAmount > 0);
        vm.assume(attackerIndex < 3); // up to 3 distinct actors
        uint amount = uint256(depositAmount);
        uint aAmount = uint256(attackerAmount);

        // Helper that re-enters on ETH receive
        ReEntrantAttacker attacker = new ReEntrantAttacker();

        // Arrange: fund the attacker and a victim
        address victim = address(uint160(uint256(keccak256(abi.encode(attackerIndex)))));
        vm.deal(victim, amount);
        vm.deal(address(attacker), aAmount);

        // Victim deposits
        vm.prank(victim);
        c.deposit{value: amount}();

        // Attacker deposits
        vm.prank(address(attacker));
        c.deposit{value: aAmount}();

        // Attacker triggers withdrawAll: during the low-level call it will re-enter and call withdrawAll again
        vm.prank(address(attacker));
        attacker.attack(address(c));

        // After all calls settle, check the attacker's credit. The correct contract resets credit to 0 after the first
        // successful send, so even though re-entrancy happens, the second withdrawAll sees credit == 0 and transfers 0.
        // The buggy contract does NOT reset credit, so the second withdrawAll transfers the same amount again.
        // Thus if credit is non-zero after both calls complete, it's a bug.
        uint finalCredit = c.credit(address(attacker));
        assertTrue(finalCredit == 0, sprintf("credit should be 0 for correct contract but is %d", finalCredit));
    }
}

contract ReEntrantAttacker {
    uint8 private reEntryCount;
    C private target;

    function attack(address _target) external payable {
        target = C(payable(_target));
        reEntryCount = 0;
        target.withdrawAll();
    }

    fallback() external payable {
        if (reEntryCount < 1) {
            reEntryCount++;
            target.withdrawAll();
        }
    }
}

