pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 withdrawCount) public {
        // Bound withdrawCount to a reasonable range to keep fuzzing fast but wide
        withdrawCount = bound(withdrawCount, 0, 5);
        // Ensure depositAmount is not zero to make credits meaningful
        vm.assume(depositAmount > 0);
        // Fund the caller and deposit
        vm.deal(caller, depositAmount * (withdrawCount + 1));
        vm.startPrank(caller);
        for (uint256 i = 0; i < withdrawCount + 1; i++) {
            c.deposit{value: depositAmount}();
        }
        // Now withdrawAll multiple times; the first withdrawAll consumes all credit,
        // subsequent ones have zero credit and expose the bug in the mutant.
        for (uint256 i = 0; i < withdrawCount + 1; i++) {
            c.withdrawAll();
        }
        vm.stopPrank();
        // General rule: after any sequence of deposits and withdrawAlls from a single caller,
        // the contract's ETH balance must equal the sum of all remaining credits (only that caller ever had credit).
        // Since we fully withdrew all credits, the contract balance should be 0.
        assertEq(address(c).balance, 0, "contract balance should match total credits");
    }
}

