pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount1, address actor1, uint256 amount2, address actor2) public {
        vm.assume(actor1 != address(0) && actor2 != address(0) && actor1 != actor2);
        vm.assume(amount1 > 0 && amount2 > 0);
        vm.assume(amount1 + amount2 >= amount1); // no overflow
        vm.deal(actor1, amount1);
        vm.deal(actor2, amount2);
        vm.deal(address(c), 0);

        vm.prank(actor1);
        c.deposit{value: amount1}();
        vm.prank(actor2);
        c.deposit{value: amount2}();

        // make one actor withdraw all, possibly triggering underflow in mutant when zero-credit guard is missing
        vm.prank(actor1);
        c.withdrawAll();
        // now actor1 credit is 0

        // actor2 withdraws
        vm.prank(actor2);
        c.withdrawAll();

        // after all withdraws, the contract should have zero balance in the correct version.
        // The mutant underflowed balance when actor1 called withdrawAll the second time (credit 0),
        // leaving a huge balance that lets actor2 drain more ETH than deposited.
        // Rule: contract ETH balance must never exceed the sum of credits of all addresses that ever deposited.
        assertTrue(address(c).balance <= amount1 + amount2);
    }
